// FCAP Jr R35 - importacao local com revisao e escrita confirmada, sem credenciais privadas.
import {FIELDS,LIMIT_ROWS,MAX_FILE_BYTES,detectHeaderMap,detectDelimiter,parseDelimited,matrixDataset,arrayDataset,jsonDatasets,vcardDataset,xmlDatasets,normalizeKey,safeText,numberBR,normalizedPhone,dedupKey,normalizePriority,normalizeTemperature,suggestStage,likelyDatasets} from './importar-core.mjs';
const config=window.FCAP_CONFIG||{};
const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','\'':'&#39;'}[x]));
const scriptURL='https://cdn.sheetjs.com/xlsx-0.20.3/package/dist/xlsx.full.min.js';
const permittedExt=new Set(['csv','tsv','txt','xlsx','xls','xlsm','xlsb','ods','fods','numbers','json','xml','vcf','vcard','html','htm','dbf','dif','slk','prn']);
const bookExt=new Set(['xlsx','xls','xlsm','xlsb','ods','fods','numbers','dbf','dif','slk','prn']);
let db=null,user=null,member=null,stages=[],members=[],existingKeys=new Set(),datasets=[],active=null,mapping={},stageMapping={},ownerMapping={},lastReport=null,ready=false, busy=false;
const setStatus=(message,type='info')=>{$('status').textContent=message;$('status').dataset.type=type};
const extOf=name=>String(name||'').split('.').pop().toLowerCase();
const encoded= v=>safeText(v,2000);
const warning=(text)=>`<p class="imp-warning">${esc(text)}</p>`;
function disableImport(disabled=true){$('import-confirm').disabled=disabled;}
function bookReady(){return !!window.XLSX}
async function loadSheet(){if(bookReady())return window.XLSX;setStatus('Carregando leitor de planilhas…');await new Promise((resolve,reject)=>{const el=document.createElement('script');el.src=scriptURL;el.async=true;el.onload=resolve;el.onerror=()=>reject(Error('Falha no carregamento do leitor Excel. Verifique a conexão com cdn.sheetjs.com.'));document.head.appendChild(el)});if(!bookReady())throw Error('A biblioteca de planilhas não ficou disponível.');return window.XLSX}
function decode(bytes){const mode=$('encoding').value;if(mode!=='auto')return new TextDecoder(mode).decode(bytes);if(bytes[0]===255&&bytes[1]===254)return new TextDecoder('utf-16le').decode(bytes);if(bytes[0]===254&&bytes[1]===255)return new TextDecoder('utf-16be').decode(bytes);try{return new TextDecoder('utf-8',{fatal:true}).decode(bytes)}catch{return new TextDecoder('windows-1252').decode(bytes)}}
function workbookDatasets(sheet,name){let out=[];for(const sheetName of sheet.SheetNames.slice(0,20)){const raw=sheet.Sheets[sheetName];const matrix=window.XLSX.utils.sheet_to_json(raw,{header:1,defval:'',raw:false,blankrows:false});if(matrix.length>1)out.push(matrixDataset(matrix,`${name} · ${sheetName}`))}if(!out.length)throw Error('Não encontrei uma aba com registros.');return out}
async function parseBytes(bytes,name){const extension=extOf(name);
 if(bytes.length>MAX_FILE_BYTES)throw Error('Arquivo acima de 20 MB. Exporte em partes menores.');
 if(bookExt.has(extension)){const x=await loadSheet();const book=x.read(bytes,{type:'array',cellFormula:false,cellHTML:false,cellDates:false});return workbookDatasets(book,name)}
 const text=decode(bytes);
 if(extension==='json')return jsonDatasets(JSON.parse(text));
 if(extension==='vcf'||extension==='vcard')return[vcardDataset(text)];
 if(extension==='xml'){const xml=new DOMParser();return xmlDatasets(text,x=>xml.parseFromString(x,'application/xml'))}
 if(extension==='html'||extension==='htm'){const documentHTML=new DOMParser().parseFromString(text,'text/html');const tables=Array.from(documentHTML.querySelectorAll('table')).slice(0,15);if(!tables.length)throw Error('HTML sem tabelas exportáveis.');return tables.map((t,i)=>matrixDataset(Array.from(t.rows).map(r=>Array.from(r.cells).map(c=>c.textContent||'')),`${name} · tabela ${i+1}`))}
 if(extension==='csv'||extension==='tsv'||extension==='txt'){const sep=extension==='tsv'?'\t':detectDelimiter(text);return[matrixDataset(parseDelimited(text,sep),name)]}
 throw Error(`Formato .${extension} não reconhecido. Exporte contatos ou negócios em CSV/Excel/JSON.`);
}
async function unpackZip(bytes,name){setStatus('Lendo arquivos do ZIP localmente…');const mod=await import('https://cdn.jsdelivr.net/npm/jszip@3.10.1/+esm');const JSZip=mod.default||mod;const zip=await JSZip.loadAsync(bytes);const entries=Object.values(zip.files).filter(f=>!f.dir&&!/^__MACOSX\//i.test(f.name)&&permittedExt.has(extOf(f.name))).sort((a,b)=>/deal|negoc|lead|oportun|contact|contat/i.test(b.name)-/deal|negoc|lead|oportun|contact|contat/i.test(a.name));if(!entries.length)throw Error('ZIP sem CSV, Excel, JSON, XML ou vCard compatíveis.');if(entries.length>20)throw Error('ZIP com mais de 20 arquivos compatíveis. Separe os módulos da exportação.');let total=0,all=[];for(const entry of entries){const hint=entry._data?.uncompressedSize;if(hint>MAX_FILE_BYTES)throw Error(`Arquivo ${entry.name} excede 20 MB descompactado.`);total+=Number(hint||0);if(total>40*1024*1024)throw Error('ZIP excede 40 MB de dados descompactados. Divida-o.');const arr=await entry.async('uint8array');if(arr.byteLength>MAX_FILE_BYTES)throw Error(`Arquivo descompactado grande demais: ${entry.name}`);let child=[];try{child=await parseBytes(arr,entry.name)}catch(err){if(entries.length===1)throw err;continue}all.push(...child.map(s=>({...s,label:entry.name+' · '+s.label})));if(all.length>30)throw Error('ZIP contém muitas planilhas/abas. Separe os arquivos.')}if(!all.length)throw Error('Nenhum arquivo útil encontrado no ZIP. Exporte apenas negócios/leads.');return all}
async function readInput(file){if(!file)throw Error('Selecione um arquivo primeiro.');if(file.size>MAX_FILE_BYTES*2)throw Error('O arquivo excede 40 MB. Divida a exportação.');const ext=extOf(file.name);if(!permittedExt.has(ext)&&ext!=='zip')throw Error('Formato não aceito. Use exportação tabular, JSON, XML, vCard ou ZIP.');const bytes=new Uint8Array(await file.arrayBuffer());return ext==='zip'?unpackZip(bytes,file.name):parseBytes(bytes,file.name)}
async function authenticate(){if(!/^https:\/\/[a-z0-9.-]+\/?$/i.test(config.supabaseUrl||'')||!config.supabaseAnonKey)throw Error('FCAP_CONFIG não está configurado.');const m=await import('https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.57.0/+esm');db=m.createClient(config.supabaseUrl,config.supabaseAnonKey,{auth:{persistSession:true,autoRefreshToken:true}});const auth=await db.auth.getUser();if(auth.error||!auth.data?.user)throw Error('Faça login no CRM antes de importar.');user=auth.data.user;
 const r=await db.from('fcap_members').select('user_id,role,active,permissions,full_name').eq('user_id',user.id).maybeSingle();if(r.error||!r.data?.active)throw Error('Sua conta não está autorizada no CRM.');member=r.data;
 const roles=['admin','diretor','gerente','gestor'];const perms=Array.isArray(member.permissions)?member.permissions:[];
 if(!roles.includes(member.role)||!(member.role==='admin'||(perms.includes('leads.export')&&perms.includes('leads.edit'))))throw Error('A importação em lote é exclusiva da gestão com permissão de importar leads.');
 const [stageResult,people]=await Promise.all([db.from('fcap_stages').select('id,name,kind,position').order('position'),db.from('fcap_members').select('user_id,full_name,email,active,role').eq('active',true)]);
 if(stageResult.error||!stageResult.data?.length)throw Error('O pipeline não tem etapas acessíveis. Configure as etapas antes de importar.');stages=stageResult.data;
 if(!people.error)members=people.data||[];
 $('identity').textContent=`${member.full_name} · ${member.role}`;ready=true;$('choose').disabled=false;setStatus('Autenticado. Selecione a exportação do CRM antigo.');
}
function selectDataset(index){active=datasets[index];if(!active)return;mapping=detectHeaderMap(active.headers);stageMapping={};ownerMapping={};lastReport=null;$('result').hidden=true;
 $('dataset').value=String(index);$('dataset-label').textContent=`${active.rows.length} registros · ${active.headers.length} colunas`;
 renderMapping();}
function fieldOptions(selected){return`<option value="">— Não importar —</option>`+active.headers.map((h,i)=>`<option value="${i}" ${String(i)===String(selected)?'selected':''}>${esc(h)}</option>`).join('')}
function renderMapping(){const rows=FIELDS.map(([key,label,hint])=>`<label class="imp-map-field"><span>${esc(label)}</span><select data-field="${key}">${fieldOptions(mapping[key])}</select><small>${esc(hint)}</small></label>`).join('');$('fields').innerHTML=rows;
 $('mapping-card').hidden=false;$('steps').dataset.step='2';renderAssignments();}
function mapped(row,field){const index=mapping[field];return index==null||index===''?'':String(row[Number(index)]??'').trim()}
function distinct(field){const set=new Set();for(const row of active.rows){const value=mapped(row,field);if(value)set.add(value)}return [...set].slice(0,51)}
function options(items,selected,missingLabel){return `<option value="">${esc(missingLabel)}</option>`+items.map(i=>`<option value="${esc(i.id)}" ${selected===i.id?'selected':''}>${esc(i.name)}</option>`).join('')}
function renderAssignments(){const oldStages=stageMapping,oldOwners=ownerMapping;stageMapping={};ownerMapping={};const uniqueStages=distinct('stage');const uniqueOwners=distinct('assigned_to');
 if(uniqueStages.length>50)throw Error('Mais de 50 etapas diferentes: verifique se a coluna selecionada é mesmo Etapa.');
 if(uniqueOwners.length>50)throw Error('Mais de 50 responsáveis diferentes: confira a coluna mapeada.');
 $('stage-map').innerHTML= uniqueStages.length ? uniqueStages.map((st,i)=>{const selected=oldStages[st]??suggestStage(st,stages);stageMapping[st]=selected||'';return `<label class="imp-pair"><span title="${esc(st)}">${esc(st)}</span><select data-stage="${i}">${options(stages.map(s=>({id:s.id,name:s.name})),stageMapping[st],'Selecione a etapa FCAP Jr.')}</select></label>`}).join(''): `<p class="imp-info">Arquivo sem coluna de etapa. Todos entrarão na etapa padrão selecionada abaixo.</p>`;
 $('owner-map').innerHTML=uniqueOwners.length?uniqueOwners.map((name,i)=>{let value=oldOwners[name];if(value===undefined){const found=members.find(m=>normalizeKey(m.full_name)===normalizeKey(name)||normalizeKey(m.email)===normalizeKey(name));value=found?.user_id||''}ownerMapping[name]=value;return`<label class="imp-pair"><span title="${esc(name)}">${esc(name)}</span><select data-owner="${i}">${options(members.map(m=>({id:m.user_id,name:m.full_name+' ('+m.role+')'})),value,'Sem responsável')}</select></label>`}).join(''):`<p class="imp-info">Arquivo sem coluna de responsável; os leads ficarão sem responsável.</p>`;
 $('default-stage').innerHTML=stages.map((s,i)=>`<option value="${esc(s.id)}" ${i===0?'selected':''}>${esc(s.name)}</option>`).join('');
 renderPreview();}
function safeURL(v,platform=''){let s=String(v||'').trim();if(!s)return '';if(platform&&/^@[a-z0-9._-]{1,80}$/i.test(s))s='https://www.'+platform+'.com/'+s.slice(1);if(!/^https?:\/\//i.test(s)&&/^[a-z0-9.-]+\.[a-z]{2,}/i.test(s))s='https://'+s;try{const u=new URL(s);return /^https?:$/.test(u.protocol)?u.href.slice(0,350):''}catch{return''}}
function sourceMeta(row){const used=new Set(Object.values(mapping).filter(x=>x!==''&&x!=null).map(Number));const extras=[];for(let i=0;i<active.headers.length;i++){if(used.has(i))continue;const key=active.headers[i],v=safeText(row[i],180);if(!v||/password|senha|secret|chave privada|token|api key|access key|refresh|credencial/i.test(key))continue;extras.push(`${safeText(key,90)}: ${v}`);if(extras.length>=16)break}return extras.join(' | ').slice(0,2000)}
function rowPayload(row){const get=f=>mapped(row,f),company=safeText(get('company_name')||get('contact_name'),180);if(company.length<2)return{error:'Empresa/nome com menos de 2 caracteres'};
 const email=safeText(get('email'),180);if(email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))return{error:`E-mail inválido: ${email.slice(0,35)}`};
 const amount=numberBR(get('estimated_value'));if(!Number.isFinite(amount))return{error:'Valor estimado inválido'};
 const rawStage=get('stage'),stage_id=rawStage?(stageMapping[rawStage]||''):$('default-stage').value;if(!stage_id)return{error:'Etapa não mapeada: '+rawStage.slice(0,60)};
 const rawOwner=get('assigned_to'),assigned_to=rawOwner?(ownerMapping[rawOwner]||null):null;
 let notes=safeText(get('notes'),2800);if($('keep-extra').checked){const extra=sourceMeta(row);if(extra)notes=(notes?notes+'\n':'')+'Campos adicionais do CRM de origem: '+extra}notes=notes.slice(0,4800);
 return{company_name:company,contact_name:safeText(get('contact_name'),120),email,phone:safeText(get('phone'),40),segment:safeText(get('segment'),140),role_title:safeText(get('role_title'),120),need:safeText(get('need'),400),source:safeText(get('source'),120)||'Importação de CRM externo',notes,stage_id,assigned_to,priority:normalizePriority(get('priority')),temperature:normalizeTemperature(get('temperature')),estimated_value:amount,website_url:safeURL(get('website_url')),instagram_url:safeURL(get('instagram_url'),'instagram'),linkedin_url:safeURL(get('linkedin_url'),'linkedin'),tiktok_url:safeURL(get('tiktok_url'),'tiktok')};
}
function evaluateRows(){const all=[],seen=new Set();let invalid=0,dupeFile=0,dupeDB=0;const errors=[];for(let i=0;i<active.rows.length;i++){const item=rowPayload(active.rows[i]);if(item.error){invalid++;if(errors.length<10)errors.push(`Linha ${i+2}: ${item.error}`);continue}const key=dedupKey(item);if(seen.has(key)&&$('skip-dupes').checked){dupeFile++;continue}seen.add(key);if(existingKeys.has(key)&&$('skip-dupes').checked){dupeDB++;continue}all.push(item)}return{all,invalid,dupeFile,dupeDB,errors}}
function renderPreview(){disableImport();if(!active)return;const summary=evaluateRows();const missing=Object.values(stageMapping).filter(x=>!x).length;
 $('preview-meta').textContent=`${active.rows.length} registros na origem · ${summary.all.length} prontos · ${summary.invalid} com erro · ${summary.dupeFile+summary.dupeDB} duplicados ignorados`;
 let table=summary.all.slice(0,8).map(l=>`<tr><td>${esc(l.company_name)}</td><td>${esc(l.contact_name)}</td><td>${esc(l.email)}</td><td>${esc(l.phone)}</td><td>${esc(stages.find(s=>s.id===l.stage_id)?.name||'')}</td><td>${Number(l.estimated_value).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})}</td></tr>`).join('');
 $('preview-table').innerHTML=table||'<tr><td colspan="6">Nenhuma linha pronta. Confira os mapeamentos.</td></tr>';
 $('errors').innerHTML=summary.errors.map(warning).join('')+(missing?warning(`${missing} etapas do arquivo aguardam correspondência manual.`):'');
 $('confirm-count').textContent=summary.all.length.toLocaleString('pt-BR');$('review-card').hidden=false;$('steps').dataset.step='3';disableImport(!summary.all.length||summary.invalid>0||missing>0||!$('legal-confirm').checked||$('db-checked').dataset.ok!=='true');
}
async function checkDuplicates(){if(!active||busy)return;busy=true;$('scan-db').disabled=true;setStatus('Analisando duplicados no CRM…');try{
 const {count,error:cError}=await db.from('fcap_leads').select('id',{head:true,count:'exact'});if(cError)throw cError;
 if(count>20000)throw Error('A base tem mais de 20 mil leads. Para evitar conferência incompleta, solicite importação assistida.');
 const leads=[];for(let offset=0;offset<(count||0);offset+=800){const {data,error}=await db.from('fcap_leads').select('company_name,contact_name,email,phone,stage_id,estimated_value').range(offset,Math.min(offset+799,(count||0)-1)).order('created_at',{ascending:true});if(error)throw error;leads.push(...(data||[]))}
 if(leads.length!==count)throw Error('Não foi possível conferir todos os leads visíveis. A importação foi bloqueada.');existingKeys=new Set(leads.map(dedupKey));$('db-checked').dataset.ok='true';$('db-checked').textContent=`Base conferida: ${count} leads visíveis`;
 setStatus('Conferência concluída. Revise o resultado antes de importar.','success');renderPreview();
 }catch(e){setStatus(e.message||String(e),'error');$('db-checked').dataset.ok='false';disableImport()}
 finally{busy=false;$('scan-db').disabled=false}}
function offerReport(report){lastReport=report;$('result').hidden=false;$('result').innerHTML=`<h2>Resultado da importação</h2><p>${esc(report.message)}</p><p><strong>${report.inserted} importados</strong> · ${report.skipped} ignorados · ${report.failed} pendentes/erro</p><button type="button" id="download-log" class="imp-subtle">Baixar relatório JSON (sem dados pessoais)</button><p><a href="./#pipeline">Voltar ao pipeline</a></p>`;$('result').scrollIntoView({behavior:'smooth',block:'start'})}
async function runImport(){if(busy||!ready||!active||!$('legal-confirm').checked||$('db-checked').dataset.ok!=='true')return;const summary=evaluateRows();if(summary.invalid||Object.values(stageMapping).some(s=>!s)||!summary.all.length)throw Error('Revise erros, etapas e duplicados antes de confirmar.');if(!window.confirm(`Importar ${summary.all.length} leads para a FCAP Jr.? Os registros existentes não serão alterados.`))return;
 busy=true;disableImport();$('choose').disabled=true;setStatus('Importando… Não feche esta página.');let inserted=0,errorText='',failed=0;
 try{const verify=await db.auth.getUser();if(verify.error||verify.data?.user?.id!==user.id)throw Error('Sessão expirada. Faça login novamente.');
 for(let offset=0;offset<summary.all.length;offset+=100){const batch=summary.all.slice(offset,offset+100);const {error}=await db.from('fcap_leads').insert(batch);if(error){failed=summary.all.length-offset;errorText=error.message;break}inserted+=batch.length;setStatus(`Importados ${inserted} de ${summary.all.length}.`, 'success')}
 const completed=inserted===summary.all.length;offerReport({version:'R35',date:new Date().toISOString(),file:$('file').files[0]?.name||'desconhecido',dataset:active.label,total:active.rows.length,inserted,skipped:summary.dupeFile+summary.dupeDB,invalid:summary.invalid,failed,error:errorText,message:completed?'Importação concluída. Os leads foram adicionados às etapas escolhidas.':'Importação interrompida. Não repita sem conferir o CRM; os lotes anteriores podem ter sido gravados.'});
 if(!completed)setStatus(`Importação parcial: ${inserted} salvos. ${errorText}`,'error');else setStatus(`Importação concluída: ${inserted} leads adicionados. Confira o pipeline.`,'success');
 }catch(e){offerReport({version:'R35',date:new Date().toISOString(),file:$('file').files[0]?.name||'',dataset:active.label,total:active.rows.length,inserted,skipped:summary.dupeFile+summary.dupeDB,invalid:summary.invalid,failed:summary.all.length-inserted,error:String(e.message||e),message:'Falha ou sessão expirada. Confira a base antes de qualquer repetição.'});setStatus(e.message||String(e),'error')}
 finally{busy=false;$('choose').disabled=false;disableImport()}}
$('choose').addEventListener('click',()=>$('file').click());
$('file').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;busy=true;disableImport();$('mapping-card').hidden=true;$('review-card').hidden=true;$('result').hidden=true;datasets=[];active=null;existingKeys=new Set();$('db-checked').dataset.ok='false';$('db-checked').textContent='Base ainda não conferida';try{setStatus(`Lendo ${file.name}…`);datasets=likelyDatasets(await readInput(file));if(!datasets.length)throw Error('Nenhum conjunto de registros encontrado.');$('dataset').innerHTML=datasets.map((d,i)=>`<option value="${i}">${esc(d.label)} · ${d.rows.length} linhas</option>`).join('');$('dataset-card').hidden=false;selectDataset(0);setStatus(`Arquivo lido localmente: ${datasets.length} conjunto(s). Confira o mapeamento.`,'success')}catch(e){setStatus(e.message||String(e),'error');$('dataset-card').hidden=true}finally{busy=false}});
$('dataset').addEventListener('change',e=>{try{selectDataset(Number(e.target.value))}catch(err){setStatus(err.message,'error')}});
$('fields').addEventListener('change',e=>{if(!e.target.dataset.field)return;const newIndex=e.target.value;if(newIndex&&Object.entries(mapping).some(([k,v])=>k!==e.target.dataset.field&&v===newIndex)){e.target.value=mapping[e.target.dataset.field]||'';setStatus('Cada coluna da origem só pode ser usada em um campo. Desmarque a correspondência anterior.','error');return}mapping[e.target.dataset.field]=newIndex;try{renderAssignments()}catch(err){setStatus(err.message,'error');disableImport()}});
$('stage-map').addEventListener('change',e=>{if(e.target.dataset.stage==null)return;const key=distinct('stage')[Number(e.target.dataset.stage)];stageMapping[key]=e.target.value;renderPreview()});
$('owner-map').addEventListener('change',e=>{if(e.target.dataset.owner==null)return;const key=distinct('assigned_to')[Number(e.target.dataset.owner)];ownerMapping[key]=e.target.value;renderPreview()});
for(const id of ['default-stage','keep-extra','skip-dupes','legal-confirm'])$(id).addEventListener('change',renderPreview);
$('scan-db').addEventListener('click',checkDuplicates);
$('import-confirm').addEventListener('click',()=>runImport().catch(e=>setStatus(e.message,'error')));
$('result').addEventListener('click',e=>{if(e.target?.id!=='download-log'||!lastReport)return;const blob=new Blob([JSON.stringify(lastReport,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='relatorio_importacao_fcapjr_r35.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)});
authenticate().catch(e=>{setStatus(e.message||String(e),'error');$('choose').disabled=true});
